        public static readonly Dictionary<string, Dictionary<string, string>> Loc = new Dictionary<string, Dictionary<string, string>>
        {
                ["de-DE"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="Realistische Fahrzeit (korrigiert angezeigte Zeiten)", ["opt.RealisticTravelTime.D"]="Die spieleigene Schätzung, wie lange eine Linie braucht, liegt unter dem echten, simulierten Umlauf — Busse beschleunigen und bremsen an jeder Haltestelle, was die Schätzung ignoriert (live gemessen etwa 1,7x auf dünnen Linien bis ~2,5x auf haltestellendichten). Aktiviere dies, und der Mod misst den echten Umlauf jeder Linie und trägt realistische Haltezeiten ein, sodass der Fahrplan dem entspricht, was die Busse tatsächlich tun. Kostet nichts — es macht die Uhr nur ehrlich. Standardmäßig AUS; bestehende Fahrpläne bleiben unverändert, bis du es aktivierst.", ["opt.ProvisionRealFleet.L"]="Fuhrpark an reale Fahrzeit anpassen (erhöht die Fahrzeuganzahl)", ["opt.ProvisionRealFleet.D"]="Bemisst außerdem die Fahrzeuganzahl jeder Linie an ihrem ECHTEN Umlauf statt an der Schätzung. Dies ist die Option, die Geld kostet: einen engen Takt auf einer Linie zu halten, deren echter Umlauf ~2x der Schätzung beträgt, benötigt etwa doppelt so viele Fahrzeuge und doppelten Unterhalt. AUS (Standard) behält die schätzungsbasierte Anzahl, sodass eine Linie unbemerkt einen längeren effektiven Takt fährt als eingestellt; AN legt für den echten Umlauf aus. Nur aufstockend — es senkt eine Linie nie unter die Schätzung — und begrenzt, damit eine fehlerhafte Messung dich nicht mit Bussen überflutet.", ["opt.StopAtEveryStop.L"]="An jeder Haltestelle halten (auch an leeren)", ["opt.StopAtEveryStop.D"]="Standardmäßig lässt Cities: Skylines II einen Bus eine Haltestelle ÜBERSPRINGEN, an der niemand wartet und niemand aussteigen will — er bremst nur ab und rollt durch, sodass diese Haltestelle nie bis zur planmäßigen Abfahrt gehalten wird und der Bus seinem Fahrplan vorauslaufen kann. Die Endhaltestelle wird nun unabhängig von dieser Einstellung immer zum Halten gezwungen (sie zu überspringen würde den ganzen Fahrplan sprengen). Aktiviere dies, um Busse zu zwingen, an JEDER Haltestelle einer getakteten Linie zu halten, sodass jede angezeigte Zeit eingehalten wird — auf Kosten einer kurzen Standzeit an jeder leeren Haltestelle, die Linien etwas langsamer macht. Betrifft nur Busse und andere Straßenfahrzeuge; Züge, Straßenbahnen, Schiffe und Flugzeuge halten bereits an jeder Station. Standardmäßig AUS.", ["opt.RealisticTripsCompat.L"]="Realistic Trips / Zeitlupen-Kompatibilität — AN, wenn du RT oder Time2Work nutzt (ALPHA)", ["opt.RealisticTripsCompat.D"]="Standardmäßig AUS — lass es aus, außer du nutzt einen Mod, der den Spieltag verlängert (Time2Work / \"Realistic Trips\" oder ähnlich). Aktiviere es mit einem solchen Mod, und Abfahrten, Haltezeiten und Flottengrößen bleiben korrekt, statt zu früh zu laufen; der Mod misst die echte Taglänge automatisch. Ohne Zeitlupen-Mod bewirkt diese Einstellung nichts, und erkennt der Mod einen solchen, während dies AUS ist, vermerkt er es im Log. HINWEIS: Dieser Kompatibilitätspfad ist ALPHA und wurde noch NICHT im Spiel mit Realistic Trips getestet — bitte melde alles Auffällige. Unter Realistic Trips nutzen deine Linien korrekterweise weniger Fahrzeuge als zuvor.", ["opt.MorningPeakStart.L"]="Beginn der Morgenspitze", ["opt.MorningPeakStart.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit beginnt.", ["opt.MorningPeakEnd.L"]="Ende der Morgenspitze", ["opt.MorningPeakEnd.D"]="Stunde, zu der die morgendliche Hauptverkehrszeit endet.", ["opt.EveningPeakStart.L"]="Beginn der Abendspitze", ["opt.EveningPeakStart.D"]="Stunde, zu der die abendliche Hauptverkehrszeit beginnt.", ["opt.EveningPeakEnd.L"]="Ende der Abendspitze", ["opt.EveningPeakEnd.D"]="Stunde, zu der die abendliche Hauptverkehrszeit endet.", ["opt.NightStart.L"]="Nachtbeginn", ["opt.NightStart.D"]="Stunde, zu der der Nachtbetrieb beginnt (kann über Mitternacht hinausgehen).", ["opt.NightEnd.L"]="Nachtende", ["opt.NightEnd.D"]="Stunde, zu der der Nachtbetrieb endet.", ["opt.Enabled.L"]="TransitTimetables aktivieren", ["opt.Enabled.D"]="Hauptschalter für den gesamten Mod. Aus = exakt Vanilla: jede Linie wird nicht mehr verwaltet (gehaltene Busse werden freigegeben und die vom Mod gesetzte Fahrzeuganzahl sowie der Entklumpungsfaktor werden zurückgesetzt), während deine linienbezogenen Fahrpläne erhalten bleiben, sodass ein erneutes Aktivieren sie fortsetzt. Standardmäßig AN.", ["grp.GroupWindows"]="Hauptverkehrszeiten", ["grp.GroupRealism"]="Realistische Fahrzeit", ["grp.GroupCompat"]="Kompatibilität", ["grp.GroupStops"]="Haltestellen", ["grp.GroupGeneral"]="Allgemein", ["ui.to"]="bis", ["ui.timetable"]="FAHRPLAN", ["ui.on"]="AN", ["ui.off"]="AUS", ["ui.ttNow"]="jetzt alle {i} Min · {f} Fahrzeuge", ["ui.ttNext"]="nächste: {n}", ["ui.firstDeparture"]="Erste Abfahrt", ["ui.peakInterval"]="Spitze", ["ui.offPeakInterval"]="Nebenzeit", ["ui.otherHours"]="übrige Stunden", ["ui.nightInterval"]="Nacht", ["ui.customLinePeak"]="Eigene Spitze (diese Linie)", ["ui.morningPeak"]="Morgenspitze", ["ui.eveningPeak"]="Abendspitze", ["ui.customPeakInterval"]="Eigenes Spitzenintervall", ["ui.terminusHint"]="Wähle eine Haltestelle, um ihre Abfahrten zu sehen und sie als Endhaltestelle dieser Linie festzulegen.", ["ui.noLines"]="Keine Linien bedienen diese Haltestelle.", ["ui.line"]="Linie {n}", ["ui.terminusBadge"]="Endhaltestelle", ["ui.departs"]="Abfahrt: {d}", ["ui.noDepartures"]="keine Abfahrten geplant", ["ui.notTimetabled"]="kein Fahrplan", ["ui.setTerminusThis"]="Als Endhaltestelle festlegen", ["ui.setTerminusAll"]="Als Endhaltestelle für alle Linien hier festlegen", ["ui.setTerminusHint"]="Die Endhaltestelle verankert den Fahrplan und den Fahrzeughalt; Busse werden hier ausgemustert.", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="ABFAHRTEN", ["ui.panelHint"]="Wähle eine Haltestelle, um die Abfahrten jeder Linie von dort zu sehen. Um den Fahrplan einer Linie zu bearbeiten, wähle die Linie — ihre Steuerung befindet sich im Infofenster der Linie.", ["opt.ManageVehicleCount.L"]="Fahrzeuganzahl verwalten", ["opt.ManageVehicleCount.D"]="Wenn aktiviert (Standard), legt die Mod die Fahrzeuganzahl jeder Linie mit Fahrplan so fest, dass dein gewählter Taktabstand eingehalten wird. Deaktiviere die Option, um die Fahrzeuganzahl dir selbst oder einer anderen Flotten-Mod (wie All Transit + Truck) zu überlassen – die Mod hält Abfahrten weiterhin an der Endstation zurück, sie fügt nur keine Busse hinzu und ändert keine. Eine Linie mit zu wenigen Fahrzeugen fährt dann einfach in größeren Abständen als eingestellt.", },
                ["es-ES"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="Tiempo de viaje realista (corrige los horarios publicados)", ["opt.RealisticTravelTime.D"]="La propia estimación del juego sobre lo que tarda una línea se queda corta respecto al recorrido real simulado: los autobuses aceleran y frenan en cada parada, algo que la estimación ignora (medido en vivo, alrededor de 1,7x en líneas con pocas paradas y hasta ~2,5x en las de muchas paradas). Actívalo y el mod mide el recorrido real de cada línea y publica horarios de parada realistas, de modo que el panel coincida con lo que los autobuses hacen de verdad. No cuesta nada: solo hace que el reloj sea honesto. Desactivado por defecto; los horarios existentes no se modifican hasta que lo actives.", ["opt.ProvisionRealFleet.L"]="Dimensionar la flota según el tiempo de viaje real (aumenta el número de vehículos)", ["opt.ProvisionRealFleet.D"]="Dimensiona también el número de vehículos de cada línea a su recorrido REAL en lugar de a la estimación. Esta es la opción que gasta: mantener un intervalo ajustado en una línea cuyo recorrido real es ~2x la estimación requiere aproximadamente el doble de vehículos, y el doble de mantenimiento. Desactivado (por defecto) mantiene el recuento basado en la estimación, con lo que una línea funciona en silencio con un intervalo efectivo mayor del que fijaste; activado la dimensiona para el recorrido real. Solo crece —nunca reduce una línea por debajo de la estimación— y tiene un tope, de modo que una lectura errónea no puede inundarte de autobuses.", ["opt.StopAtEveryStop.L"]="Parar en todas las paradas (incluso las vacías)", ["opt.StopAtEveryStop.D"]="Por defecto, Cities: Skylines II permite que un autobús OMITA una parada donde nadie espera y nadie quiere bajar: solo reduce la velocidad y pasa de largo, así que esa parada nunca se retiene hasta su salida programada y el autobús puede adelantarse a su horario. La terminal ahora siempre se fuerza a parar, independientemente de esta opción (omitirla dejaría colgado todo el horario). Activa esto para forzar a los autobuses a detenerse en TODAS las paradas de una línea con horario, de modo que se respeten todas las horas publicadas, a costa de una breve espera en cada parada vacía, lo que hace que las líneas vayan un poco más lentas. Afecta solo a autobuses y otros vehículos de carretera; trenes, tranvías, barcos y aviones ya paran en todas las estaciones. Desactivado por defecto.", ["opt.RealisticTripsCompat.L"]="Compatibilidad con Realistic Trips / tiempo lento — actívalo si usas RT o Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desactivado por defecto: déjalo así salvo que uses un mod que alargue el día del juego (Time2Work / \"Realistic Trips\" o similar). Actívalo con un mod de ese tipo y las salidas, los horarios de parada y el tamaño de la flota seguirán siendo correctos en lugar de adelantarse; el mod mide automáticamente la duración real del día. Sin un mod de tiempo lento, esta opción no hace nada, y si el mod detecta uno mientras esto está desactivado lo anotará en el registro. NOTA: esta vía de compatibilidad es ALFA y AÚN NO se ha probado con Realistic Trips en el juego; informa de cualquier anomalía. Con Realistic Trips, tus líneas usarán correctamente menos vehículos que antes.", ["opt.MorningPeakStart.L"]="Inicio de la hora punta de la mañana", ["opt.MorningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la mañana.", ["opt.MorningPeakEnd.L"]="Fin de la hora punta de la mañana", ["opt.MorningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la mañana.", ["opt.EveningPeakStart.L"]="Inicio de la hora punta de la tarde", ["opt.EveningPeakStart.D"]="Hora en que empieza el nivel de servicio de la hora punta de la tarde.", ["opt.EveningPeakEnd.L"]="Fin de la hora punta de la tarde", ["opt.EveningPeakEnd.D"]="Hora en que termina el nivel de servicio de la hora punta de la tarde.", ["opt.NightStart.L"]="Inicio de la noche", ["opt.NightStart.D"]="Hora en que empieza el servicio nocturno (puede pasar de la medianoche).", ["opt.NightEnd.L"]="Fin de la noche", ["opt.NightEnd.D"]="Hora en que termina el servicio nocturno.", ["opt.Enabled.L"]="Activar TransitTimetables", ["opt.Enabled.D"]="Interruptor principal de todo el mod. Desactivado = vanilla exacto: todas las líneas dejan de gestionarse (los autobuses retenidos se liberan y se revierten el recuento de flota y el factor de dispersión aplicados por el mod), mientras que tus horarios por línea se conservan para que reactivarlo los reanude. Activado por defecto.", ["grp.GroupWindows"]="Franjas de hora punta", ["grp.GroupRealism"]="Tiempo de viaje realista", ["grp.GroupCompat"]="Compatibilidad", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="General", ["ui.to"]="a", ["ui.timetable"]="HORARIO", ["ui.on"]="SÍ", ["ui.off"]="NO", ["ui.ttNow"]="ahora cada {i} min · {f} vehículos", ["ui.ttNext"]="siguiente: {n}", ["ui.firstDeparture"]="Primera salida", ["ui.peakInterval"]="Hora punta", ["ui.offPeakInterval"]="Fuera de punta", ["ui.otherHours"]="otras horas", ["ui.nightInterval"]="Noche", ["ui.customLinePeak"]="Hora punta personalizada (esta línea)", ["ui.morningPeak"]="Hora punta de la mañana", ["ui.eveningPeak"]="Hora punta de la tarde", ["ui.customPeakInterval"]="Intervalo de hora punta personalizado", ["ui.terminusHint"]="Selecciona una parada para ver sus salidas y fijarla como terminal de esta línea.", ["ui.noLines"]="Ninguna línea da servicio a esta parada.", ["ui.line"]="Línea {n}", ["ui.terminusBadge"]="terminal", ["ui.departs"]="sale: {d}", ["ui.noDepartures"]="sin salidas programadas", ["ui.notTimetabled"]="sin horario", ["ui.setTerminusThis"]="Fijar como terminal", ["ui.setTerminusAll"]="Fijar como terminal para todas las líneas de aquí", ["ui.setTerminusHint"]="La terminal ancla el horario y la retención de vehículos; los autobuses se retiran aquí.", ["ui.buttonTooltip"]="Horarios de transporte", ["ui.panelTitle"]="SALIDAS", ["ui.panelHint"]="Selecciona una parada para ver las salidas de todas las líneas desde ella. Para editar el horario de una línea, selecciona la línea: sus controles están en el panel de información de la línea.", ["opt.ManageVehicleCount.L"]="Gestionar el número de vehículos", ["opt.ManageVehicleCount.D"]="Cuando está activado (predeterminado), el mod ajusta el número de vehículos de cada línea con horario para mantener el intervalo que elijas. Desactívalo para dejar el número de vehículos en tus manos o en las de otro mod de flota (como All Transit + Truck): el mod sigue reteniendo las salidas en la terminal, solo que no añade ni cambia autobuses. Una línea con muy pocos vehículos circulará entonces con un intervalo más amplio que el establecido.", },
                ["fr-FR"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="Temps de trajet réaliste (corrige les horaires affichés)", ["opt.RealisticTravelTime.D"]="L'estimation du jeu de la durée d'une ligne sous-évalue la boucle réelle simulée — les bus accélèrent et freinent à chaque arrêt, ce que l'estimation ignore (mesuré en direct à environ 1,7x sur les lignes espacées, jusqu'à ~2,5x sur celles à arrêts rapprochés). Activez cette option et le mod mesure la boucle réelle de chaque ligne et affiche des horaires d'arrêt réalistes, pour que le tableau corresponde à ce que font vraiment les bus. Ne coûte rien — cela rend simplement l'horloge honnête. Désactivé par défaut ; les horaires existants restent inchangés jusqu'à ce que vous l'activiez.", ["opt.ProvisionRealFleet.L"]="Dimensionner la flotte selon le temps de trajet réel (augmente le nombre de véhicules)", ["opt.ProvisionRealFleet.D"]="Dimensionne aussi le nombre de véhicules de chaque ligne d'après sa boucle RÉELLE plutôt que d'après l'estimation. C'est l'option qui dépense : maintenir un intervalle serré sur une ligne dont la boucle réelle fait ~2x l'estimation demande environ deux fois plus de véhicules, et deux fois plus d'entretien. Désactivé (par défaut) conserve le nombre basé sur l'estimation, donc une ligne applique en silence un intervalle effectif plus long que celui que vous avez réglé ; activé dimensionne pour la boucle réelle. Croissance uniquement — ne réduit jamais une ligne en dessous de l'estimation — et plafonné, pour qu'une mauvaise mesure ne vous inonde pas de bus.", ["opt.StopAtEveryStop.L"]="S'arrêter à chaque arrêt (même vides)", ["opt.StopAtEveryStop.D"]="Par défaut, Cities: Skylines II autorise un bus à SAUTER un arrêt où personne n'attend et personne ne veut descendre — il ne fait que ralentir et passer, si bien que cet arrêt n'est jamais retenu jusqu'à son départ prévu et que le bus peut prendre de l'avance sur son horaire. Le terminus est désormais toujours forcé à s'arrêter quel que soit ce réglage (le sauter désorganiserait tout l'horaire). Activez cette option pour forcer les bus à s'arrêter à CHAQUE arrêt d'une ligne à horaire, afin que chaque horaire affiché soit respecté — au prix d'un court arrêt à chaque arrêt vide, ce qui ralentit un peu les lignes. Concerne uniquement les bus et autres véhicules routiers ; les trains, tramways, navires et avions s'arrêtent déjà à chaque station. Désactivé par défaut.", ["opt.RealisticTripsCompat.L"]="Compatibilité Realistic Trips / temps ralenti — activez si vous utilisez RT ou Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Désactivé par défaut — laissez-le désactivé sauf si vous utilisez un mod qui allonge la journée en jeu (Time2Work / \\\"Realistic Trips\\\" ou similaire). Activez-le avec un tel mod et les départs, horaires d'arrêt et tailles de flotte restent corrects au lieu d'être en avance ; le mod mesure automatiquement la durée réelle de la journée. Sans mod de temps ralenti ce réglage ne fait rien, et si le mod en détecte un alors que ceci est désactivé il le signalera dans le journal. NOTE : ce chemin de compatibilité est en ALPHA et n'a PAS encore été testé en jeu avec Realistic Trips — merci de signaler tout comportement étrange. Sous Realistic Trips vos lignes utiliseront correctement moins de véhicules qu'auparavant.", ["opt.MorningPeakStart.L"]="Début de la pointe du matin", ["opt.MorningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du matin.", ["opt.MorningPeakEnd.L"]="Fin de la pointe du matin", ["opt.MorningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du matin.", ["opt.EveningPeakStart.L"]="Début de la pointe du soir", ["opt.EveningPeakStart.D"]="Heure à laquelle commence le niveau de service de pointe du soir.", ["opt.EveningPeakEnd.L"]="Fin de la pointe du soir", ["opt.EveningPeakEnd.D"]="Heure à laquelle se termine le niveau de service de pointe du soir.", ["opt.NightStart.L"]="Début de nuit", ["opt.NightStart.D"]="Heure à laquelle commence le service de nuit (peut passer minuit).", ["opt.NightEnd.L"]="Fin de nuit", ["opt.NightEnd.D"]="Heure à laquelle se termine le service de nuit.", ["opt.Enabled.L"]="Activer TransitTimetables", ["opt.Enabled.D"]="Interrupteur principal de tout le mod. Désactivé = jeu de base exact : toutes les lignes cessent d'être gérées (les bus retenus sont libérés et le nombre de véhicules ainsi que le facteur de désengorgement appliqués par le mod sont rétablis), tandis que vos horaires par ligne sont conservés pour reprendre à la réactivation. Activé par défaut.", ["grp.GroupWindows"]="Plages de pointe", ["grp.GroupRealism"]="Temps de trajet réaliste", ["grp.GroupCompat"]="Compatibilité", ["grp.GroupStops"]="Arrêts", ["grp.GroupGeneral"]="Général", ["ui.to"]="à", ["ui.timetable"]="HORAIRE", ["ui.on"]="ACTIVÉ", ["ui.off"]="DÉSACTIVÉ", ["ui.ttNow"]="actuellement toutes les {i} min · {f} véhicules", ["ui.ttNext"]="suivant : {n}", ["ui.firstDeparture"]="Premier départ", ["ui.peakInterval"]="Pointe", ["ui.offPeakInterval"]="Heures creuses", ["ui.otherHours"]="autres heures", ["ui.nightInterval"]="Nuit", ["ui.customLinePeak"]="Pointe personnalisée (cette ligne)", ["ui.morningPeak"]="Pointe du matin", ["ui.eveningPeak"]="Pointe du soir", ["ui.customPeakInterval"]="Intervalle de pointe personnalisé", ["ui.terminusHint"]="Sélectionnez un arrêt pour voir ses départs et le définir comme terminus de cette ligne.", ["ui.noLines"]="Aucune ligne ne dessert cet arrêt.", ["ui.line"]="Ligne {n}", ["ui.terminusBadge"]="terminus", ["ui.departs"]="départ : {d}", ["ui.noDepartures"]="aucun départ prévu", ["ui.notTimetabled"]="sans horaire", ["ui.setTerminusThis"]="Définir comme terminus", ["ui.setTerminusAll"]="Définir comme terminus pour toutes les lignes ici", ["ui.setTerminusHint"]="Le terminus ancre l'horaire et la rétention des véhicules ; les bus sont retirés ici.", ["ui.buttonTooltip"]="Horaires de transport", ["ui.panelTitle"]="DÉPARTS", ["ui.panelHint"]="Sélectionnez un arrêt pour voir les départs de chaque ligne depuis cet arrêt. Pour modifier l'horaire d'une ligne, sélectionnez la ligne — ses réglages se trouvent dans le panneau d'informations de la ligne.", ["opt.ManageVehicleCount.L"]="Gérer le nombre de véhicules", ["opt.ManageVehicleCount.D"]="Lorsque cette option est activée (par défaut), le mod règle le nombre de véhicules de chaque ligne dotée d'horaires afin de respecter l'intervalle que vous avez choisi. Désactivez-la pour laisser le nombre de véhicules à votre gré ou à celui d'un autre mod de flotte (comme All Transit + Truck) : le mod continue de retenir les départs au terminus, il n'ajoute ni ne modifie simplement pas les bus. Une ligne comptant trop peu de véhicules circulera alors simplement à un intervalle plus large que celui défini.", },
                ["it-IT"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="Tempo di percorrenza realistico (corregge gli orari esposti)", ["opt.RealisticTravelTime.D"]="La stima del gioco sulla durata di una linea è inferiore al percorso reale simulato: gli autobus accelerano e frenano a ogni fermata, cosa che la stima ignora (misurato dal vivo a circa 1,7x sulle linee con poche fermate, fino a ~2,5x su quelle con molte fermate). Attiva questa opzione e la mod misura il giro reale di ogni linea ed espone orari di fermata realistici, così il tabellone corrisponde a ciò che gli autobus fanno davvero. Non costa nulla: rende soltanto onesto l'orologio. Disattivata per impostazione predefinita; gli orari esistenti restano invariati finché non la abiliti.", ["opt.ProvisionRealFleet.L"]="Dimensiona la flotta in base al tempo di percorrenza reale (aumenta il numero di veicoli)", ["opt.ProvisionRealFleet.D"]="Dimensiona anche il numero di veicoli di ogni linea sul suo giro REALE anziché sulla stima. È questa l'opzione che comporta spese: mantenere una frequenza stretta su una linea il cui giro reale è ~2x la stima richiede circa il doppio dei veicoli, e il doppio dei costi di gestione. Disattivata (predefinita) mantiene il conteggio basato sulla stima, così una linea usa silenziosamente una frequenza effettiva più lunga di quella impostata; attivata dimensiona la flotta sul giro reale. Solo in aumento — non riduce mai una linea al di sotto della stima — e con un limite massimo, così una lettura errata non può inondarti di autobus.", ["opt.StopAtEveryStop.L"]="Ferma a ogni fermata (anche quelle vuote)", ["opt.StopAtEveryStop.D"]="Per impostazione predefinita Cities: Skylines II consente a un autobus di SALTARE una fermata dove nessuno è in attesa e nessuno vuole scendere — rallenta soltanto e prosegue, così quella fermata non viene mai trattenuta fino alla partenza programmata e l'autobus può portarsi in anticipo sull'orario. Il capolinea è ora sempre obbligato a fermarsi indipendentemente da questa impostazione (saltarlo comprometterebbe l'intero orario). Attiva questa opzione per obbligare gli autobus a fermarsi a OGNI fermata di una linea con orario, così ogni orario esposto viene rispettato — al prezzo di una breve sosta a ogni fermata vuota, che rende le linee un po' più lente. Riguarda solo autobus e altri veicoli su strada; treni, tram, navi e aerei si fermano già a ogni stazione. Disattivata per impostazione predefinita.", ["opt.RealisticTripsCompat.L"]="Compatibilità con Realistic Trips / tempo rallentato — attiva se usi RT o Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Disattivata per impostazione predefinita — lasciala disattivata a meno che tu non usi una mod che allunga la giornata di gioco (Time2Work / \\\"Realistic Trips\\\" o simili). Attivala con una mod di questo tipo e le partenze, gli orari di fermata e le dimensioni della flotta restano corretti anziché anticipare; la mod misura automaticamente la durata reale della giornata. Senza una mod di tempo rallentato questa impostazione non fa nulla, e se la mod ne rileva una mentre è disattivata lo segnalerà nel log. NOTA: questo percorso di compatibilità è in fase ALPHA e NON è ancora stato testato in gioco con Realistic Trips — segnala qualunque anomalia. Con Realistic Trips le tue linee useranno correttamente meno veicoli rispetto a prima.", ["opt.MorningPeakStart.L"]="Inizio picco mattutino", ["opt.MorningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco mattutino.", ["opt.MorningPeakEnd.L"]="Fine picco mattutino", ["opt.MorningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco mattutino.", ["opt.EveningPeakStart.L"]="Inizio picco serale", ["opt.EveningPeakStart.D"]="Ora in cui inizia il livello di servizio di picco serale.", ["opt.EveningPeakEnd.L"]="Fine picco serale", ["opt.EveningPeakEnd.D"]="Ora in cui termina il livello di servizio di picco serale.", ["opt.NightStart.L"]="Inizio notte", ["opt.NightStart.D"]="Ora in cui inizia il servizio notturno (può proseguire oltre la mezzanotte).", ["opt.NightEnd.L"]="Fine notte", ["opt.NightEnd.D"]="Ora in cui termina il servizio notturno.", ["opt.Enabled.L"]="Abilita TransitTimetables", ["opt.Enabled.D"]="Interruttore principale dell'intera mod. Disattivato = comportamento originale esatto: ogni linea smette di essere gestita (gli autobus eventualmente trattenuti vengono rilasciati e il conteggio della flotta e il fattore di riduzione degli ammassamenti applicati dalla mod vengono ripristinati), mentre gli orari delle singole linee vengono conservati così che riabilitandola riprendano. Attivato per impostazione predefinita.", ["grp.GroupWindows"]="Fasce di picco", ["grp.GroupRealism"]="Tempo di percorrenza realistico", ["grp.GroupCompat"]="Compatibilità", ["grp.GroupStops"]="Fermate", ["grp.GroupGeneral"]="Generale", ["ui.to"]="alle", ["ui.timetable"]="ORARIO", ["ui.on"]="ATTIVO", ["ui.off"]="DISATTIVO", ["ui.ttNow"]="ora ogni {i} min · {f} veicoli", ["ui.ttNext"]="prossima: {n}", ["ui.firstDeparture"]="Prima partenza", ["ui.peakInterval"]="Picco", ["ui.offPeakInterval"]="Fuori picco", ["ui.otherHours"]="altre ore", ["ui.nightInterval"]="Notte", ["ui.customLinePeak"]="Picco personalizzato (questa linea)", ["ui.morningPeak"]="Picco mattutino", ["ui.eveningPeak"]="Picco serale", ["ui.customPeakInterval"]="Intervallo di picco personalizzato", ["ui.terminusHint"]="Seleziona una fermata per vedere le sue partenze e impostarla come capolinea di questa linea.", ["ui.noLines"]="Nessuna linea serve questa fermata.", ["ui.line"]="Linea {n}", ["ui.terminusBadge"]="capolinea", ["ui.departs"]="parte: {d}", ["ui.noDepartures"]="nessuna partenza programmata", ["ui.notTimetabled"]="senza orario", ["ui.setTerminusThis"]="Imposta come capolinea", ["ui.setTerminusAll"]="Imposta come capolinea per tutte le linee qui", ["ui.setTerminusHint"]="Il capolinea ancora l'orario e la sosta dei veicoli; qui gli autobus vengono ritirati.", ["ui.buttonTooltip"]="Orari dei trasporti", ["ui.panelTitle"]="PARTENZE", ["ui.panelHint"]="Seleziona una fermata per vedere le partenze di ogni linea da essa. Per modificare l'orario di una linea, seleziona la linea — i suoi controlli si trovano nel pannello informazioni della linea.", ["opt.ManageVehicleCount.L"]="Gestisci il numero di veicoli", ["opt.ManageVehicleCount.D"]="Quando è attivo (predefinito), la mod imposta il numero di veicoli di ogni linea con orario per mantenere l'intervallo che hai scelto. Disattivalo per lasciare il numero di veicoli a te o a un'altra mod per la flotta (come All Transit + Truck): la mod continua a trattenere le partenze al capolinea, semplicemente non aggiunge né modifica gli autobus. Una linea con troppo pochi veicoli viaggerà quindi con un intervallo più ampio di quello impostato.", },
                ["ja-JP"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="リアルな移動時間（表示時刻を補正）", ["opt.RealisticTravelTime.D"]="路線の所要時間に関するゲーム内の推定値は、実際にシミュレートされる周回時間を過小評価します。バスは停留所ごとに加速・減速しますが、推定値はこれを無視しています（停留所の少ない路線で実測約1.7倍、停留所の多い路線で最大約2.5倍）。これをオンにすると、Modが各路線の実際の周回時間を計測し、リアルな停留所時刻を掲示するため、時刻表が実際のバスの動きと一致します。費用はかかりません。時刻を正確にするだけです。デフォルトはオフで、有効にするまで既存の時刻表は変更されません。", ["opt.ProvisionRealFleet.L"]="実際の移動時間に合わせて車両を配備（車両数が増加します）", ["opt.ProvisionRealFleet.D"]="各路線の車両数も、推定値ではなく実際の周回時間に合わせて算出します。費用が発生するのはこの設定です。実際の周回時間が推定値の約2倍になる路線で運行間隔を詰めて維持するには、およそ2倍の車両と2倍の維持費が必要です。オフ（デフォルト）では推定値に基づく車両数のままとなり、路線は設定した運行間隔よりも実質的に長い間隔で静かに運行されます。オンにすると実際の周回時間に合わせて配備します。増加のみ（推定値を下回って削減することはありません）で、上限も設けられているため、誤った計測値が大量のバスを送り込むことはありません。", ["opt.StopAtEveryStop.L"]="すべての停留所で停車（空の停留所でも）", ["opt.StopAtEveryStop.D"]="デフォルトでは、Cities: Skylines II は待っている人も降りる人もいない停留所をバスがスキップすることを許可しています。減速して通過するだけなので、その停留所では予定の発車時刻まで待機せず、バスが時刻表より先行して運行してしまいます。この設定に関わらず、終点は常に停車が強制されるようになりました（スキップすると時刻表全体が破綻するため）。これをオンにすると、時刻表のある路線のすべての停留所でバスが必ず停車するようになり、掲示されたすべての時刻が守られます。ただし空の停留所ごとに短い停車時間が発生するため、路線の運行はやや遅くなります。バスなどの道路車両にのみ影響します。列車、トラム、船舶、航空機はすでにすべての駅で停車します。デフォルトはオフです。", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 低速時間との互換性 — RT や Time2Work を使用する場合はオンに（ALPHA）", ["opt.RealisticTripsCompat.D"]="デフォルトはオフです。ゲーム内の1日を長くするMod（Time2Work / \"Realistic Trips\" など）を使用していない限り、オフのままにしてください。そのようなModと併用してこれをオンにすると、発車時刻・停留所時刻・車両数が先行せず正しく保たれます。Modが実際の1日の長さを自動的に計測します。低速時間Modがなければこの設定は何もせず、この設定がオフのときにModがそれを検出した場合はログに記録します。注意: この互換パスはALPHAであり、Realistic Trips とのゲーム内での動作検証はまだ行われていません。おかしな点があれば報告してください。Realistic Trips 使用時、路線は以前より正しく少ない車両数で運行されます。", ["opt.MorningPeakStart.L"]="朝ピークの開始", ["opt.MorningPeakStart.D"]="朝ピークの運行水準が始まる時刻。", ["opt.MorningPeakEnd.L"]="朝ピークの終了", ["opt.MorningPeakEnd.D"]="朝ピークの運行水準が終わる時刻。", ["opt.EveningPeakStart.L"]="夕ピークの開始", ["opt.EveningPeakStart.D"]="夕ピークの運行水準が始まる時刻。", ["opt.EveningPeakEnd.L"]="夕ピークの終了", ["opt.EveningPeakEnd.D"]="夕ピークの運行水準が終わる時刻。", ["opt.NightStart.L"]="夜間の開始", ["opt.NightStart.D"]="夜間運行が始まる時刻（深夜0時をまたぐ場合があります）。", ["opt.NightEnd.L"]="夜間の終了", ["opt.NightEnd.D"]="夜間運行が終わる時刻。", ["opt.Enabled.L"]="TransitTimetables を有効化", ["opt.Enabled.D"]="Mod全体のマスタースイッチ。オフ = 完全にバニラ状態: すべての路線の管理が停止し（待機中のバスは解放され、Modが適用した車両数と分散係数は元に戻ります）、路線ごとの時刻表は保持されるため再有効化すれば再開されます。デフォルトはオンです。", ["grp.GroupWindows"]="ピーク時間帯", ["grp.GroupRealism"]="リアルな移動時間", ["grp.GroupCompat"]="互換性", ["grp.GroupStops"]="停留所", ["grp.GroupGeneral"]="全般", ["ui.to"]="〜", ["ui.timetable"]="時刻表", ["ui.on"]="オン", ["ui.off"]="オフ", ["ui.ttNow"]="現在 {i}分間隔 · {f}台", ["ui.ttNext"]="次: {n}", ["ui.firstDeparture"]="始発", ["ui.peakInterval"]="ピーク", ["ui.offPeakInterval"]="オフピーク", ["ui.otherHours"]="その他の時間帯", ["ui.nightInterval"]="夜間", ["ui.customLinePeak"]="カスタムピーク（この路線）", ["ui.morningPeak"]="朝ピーク", ["ui.eveningPeak"]="夕ピーク", ["ui.customPeakInterval"]="カスタムピーク間隔", ["ui.terminusHint"]="停留所を選択すると発車時刻が表示され、その停留所をこの路線の終点に設定できます。", ["ui.noLines"]="この停留所を通る路線はありません。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終点", ["ui.departs"]="発車: {d}", ["ui.noDepartures"]="発車予定なし", ["ui.notTimetabled"]="時刻表なし", ["ui.setTerminusThis"]="終点に設定", ["ui.setTerminusAll"]="ここのすべての路線の終点に設定", ["ui.setTerminusHint"]="終点は時刻表と車両の待機を固定します。バスはここで退役します。", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="発車", ["ui.panelHint"]="停留所を選択すると、その停留所からの全路線の発車時刻が表示されます。路線の時刻表を編集するには路線を選択してください。操作項目は路線の情報パネルにあります。", ["opt.ManageVehicleCount.L"]="車両数を管理", ["opt.ManageVehicleCount.D"]="オンのとき（既定）、この Mod は時刻表を設定した各路線の車両数を調整し、指定した運行間隔を維持します。オフにすると、車両数の管理はあなた自身や他の車両編成 Mod（All Transit + Truck など）に委ねられます。Mod は終点での発車を引き続き制御しますが、バスの追加や変更は行いません。車両数が足りない路線は、設定した間隔より広い間隔で運行されます。", },
                ["ko-KR"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="현실적인 이동 시간 (게시 시각 보정)", ["opt.RealisticTravelTime.D"]="게임이 자체적으로 추정하는 노선 소요 시간은 실제 시뮬레이션되는 순환 시간보다 짧게 나옵니다 — 버스는 정류장마다 가속하고 제동하는데, 추정치는 이를 무시합니다 (실측 결과 정류장이 드문 노선은 약 1.7배, 정류장이 조밀한 노선은 약 2.5배까지 차이가 납니다). 이 옵션을 켜면 모드가 각 노선의 실제 순환 시간을 측정하여 현실적인 정류장 시각을 게시하므로, 시간표가 버스의 실제 운행과 일치합니다. 비용은 들지 않으며 — 시계를 정직하게 만들 뿐입니다. 기본값은 꺼짐이며, 켜기 전까지 기존 시간표는 변경되지 않습니다.", ["opt.ProvisionRealFleet.L"]="실제 이동 시간에 맞춰 차량 배치 (차량 수 증가)", ["opt.ProvisionRealFleet.D"]="추정치가 아니라 실제 순환 시간에 맞춰 각 노선의 차량 대수를 산정합니다. 비용이 드는 것은 바로 이 옵션입니다: 실제 순환 시간이 추정치의 약 2배인 노선에서 촘촘한 배차 간격을 유지하려면 차량이 약 2배, 유지비도 약 2배가 필요합니다. 꺼짐(기본값)은 추정 기반 대수를 유지하므로, 노선이 설정한 것보다 사실상 더 긴 배차 간격으로 조용히 운행됩니다. 켜면 실제 순환 시간에 맞춰 배치합니다. 증가 전용이며 — 추정치보다 노선 대수를 절대 줄이지 않습니다 — 상한이 걸려 있어 잘못된 측정값이 버스를 과도하게 늘리지 않습니다.", ["opt.StopAtEveryStop.L"]="모든 정류장에 정차 (빈 정류장 포함)", ["opt.StopAtEveryStop.D"]="기본적으로 Cities: Skylines II는 기다리는 사람도, 내리려는 사람도 없는 정류장을 버스가 건너뛰도록 허용합니다 — 감속하며 통과만 하므로 그 정류장은 예정된 출발 시각까지 대기하지 않고, 버스가 시간표보다 앞서 운행할 수 있습니다. 이제 종점은 이 설정과 관계없이 항상 정차하도록 강제됩니다 (건너뛰면 전체 시간표가 어긋납니다). 이 옵션을 켜면 시간표가 적용된 노선의 모든 정류장에 버스가 진입하여 정차하도록 강제하므로 게시된 모든 시각이 지켜집니다 — 빈 정류장마다 잠시 정차하는 대가로 노선이 조금 느려집니다. 버스와 기타 도로 차량에만 영향을 주며, 기차·트램·선박·항공기는 이미 모든 역에 정차합니다. 기본값은 꺼짐입니다.", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 느린 시간 호환 — RT나 Time2Work을 사용하면 켜세요 (알파)", ["opt.RealisticTripsCompat.D"]="기본값은 꺼짐 — 게임 내 하루 길이를 늘리는 모드(Time2Work / \"Realistic Trips\" 등)를 사용하지 않는 한 꺼진 채로 두세요. 그런 모드와 함께 이 옵션을 켜면 출발 시각, 정류장 시각, 차량 대수가 앞서 운행하지 않고 정확하게 유지됩니다. 모드가 실제 하루 길이를 자동으로 측정합니다. 느린 시간 모드가 없으면 이 설정은 아무 효과가 없으며, 이 옵션이 꺼진 상태에서 그런 모드가 감지되면 로그에 기록됩니다. 참고: 이 호환 경로는 알파이며 아직 게임 내에서 Realistic Trips와 함께 테스트되지 않았습니다 — 이상한 점이 있으면 제보해 주세요. Realistic Trips에서는 노선이 이전보다 올바르게 더 적은 차량을 사용합니다.", ["opt.MorningPeakStart.L"]="오전 첨두 시작", ["opt.MorningPeakStart.D"]="오전 첨두 운행 수준이 시작되는 시각입니다.", ["opt.MorningPeakEnd.L"]="오전 첨두 종료", ["opt.MorningPeakEnd.D"]="오전 첨두 운행 수준이 끝나는 시각입니다.", ["opt.EveningPeakStart.L"]="오후 첨두 시작", ["opt.EveningPeakStart.D"]="오후 첨두 운행 수준이 시작되는 시각입니다.", ["opt.EveningPeakEnd.L"]="오후 첨두 종료", ["opt.EveningPeakEnd.D"]="오후 첨두 운행 수준이 끝나는 시각입니다.", ["opt.NightStart.L"]="야간 시작", ["opt.NightStart.D"]="야간 운행이 시작되는 시각입니다 (자정을 넘길 수 있음).", ["opt.NightEnd.L"]="야간 종료", ["opt.NightEnd.D"]="야간 운행이 끝나는 시각입니다.", ["opt.Enabled.L"]="TransitTimetables 활성화", ["opt.Enabled.D"]="모드 전체의 주 스위치입니다. 꺼짐 = 완전한 기본 게임: 모든 노선의 관리가 중단되고(대기 중이던 버스는 해제되며 모드가 적용한 차량 대수와 뭉침 방지 계수가 되돌려집니다), 다시 켜면 이어갈 수 있도록 노선별 시간표는 유지됩니다. 기본값은 켜짐입니다.", ["grp.GroupWindows"]="첨두 시간대", ["grp.GroupRealism"]="현실적인 이동 시간", ["grp.GroupCompat"]="호환성", ["grp.GroupStops"]="정류장", ["grp.GroupGeneral"]="일반", ["ui.to"]="~", ["ui.timetable"]="시간표", ["ui.on"]="켜짐", ["ui.off"]="꺼짐", ["ui.ttNow"]="현재 {i}분 간격 · 차량 {f}대", ["ui.ttNext"]="다음: {n}", ["ui.firstDeparture"]="첫차 출발", ["ui.peakInterval"]="첨두", ["ui.offPeakInterval"]="비첨두", ["ui.otherHours"]="그 외 시간", ["ui.nightInterval"]="야간", ["ui.customLinePeak"]="사용자 지정 첨두 (이 노선)", ["ui.morningPeak"]="오전 첨두", ["ui.eveningPeak"]="오후 첨두", ["ui.customPeakInterval"]="사용자 지정 첨두 간격", ["ui.terminusHint"]="정류장을 선택하면 출발 시각을 확인하고 이 노선의 종점으로 설정할 수 있습니다.", ["ui.noLines"]="이 정류장을 지나는 노선이 없습니다.", ["ui.line"]="{n}번 노선", ["ui.terminusBadge"]="종점", ["ui.departs"]="출발: {d}", ["ui.noDepartures"]="예정된 출발 없음", ["ui.notTimetabled"]="시간표 미설정", ["ui.setTerminusThis"]="종점으로 설정", ["ui.setTerminusAll"]="여기의 모든 노선을 종점으로 설정", ["ui.setTerminusHint"]="종점은 시간표와 차량 대기의 기준점이며, 버스는 이곳에서 퇴역합니다.", ["ui.buttonTooltip"]="Transit Timetables", ["ui.panelTitle"]="출발 시각", ["ui.panelHint"]="정류장을 선택하면 그 정류장의 모든 노선 출발 시각을 볼 수 있습니다. 노선의 시간표를 편집하려면 노선을 선택하세요 — 관련 설정은 노선의 정보 패널에 있습니다.", ["opt.ManageVehicleCount.L"]="차량 수 관리", ["opt.ManageVehicleCount.D"]="켜면(기본값) 이 모드가 시간표가 설정된 각 노선의 차량 수를 조정하여 지정한 배차 간격을 유지합니다. 끄면 차량 수 관리는 사용자 또는 다른 차량 관리 모드(All Transit + Truck 등)에 맡겨집니다. 모드는 종점에서의 출발을 계속 제어하지만 버스를 추가하거나 변경하지는 않습니다. 차량이 너무 적은 노선은 설정한 간격보다 더 넓은 간격으로 운행됩니다.", },
                ["pl-PL"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="Realistyczny czas przejazdu (koryguje podane godziny)", ["opt.RealisticTravelTime.D"]="Wbudowana w grę ocena czasu przejazdu linii jest zaniżona wobec rzeczywistej, symulowanej pętli — autobusy przyspieszają i hamują na każdym przystanku, czego ta ocena nie uwzględnia (zmierzone na żywo: około 1,7x na liniach z rzadkimi przystankami, do ~2,5x na liniach z gęstymi przystankami). Włącz tę opcję, a mod zmierzy rzeczywistą pętlę każdej linii i poda realistyczne godziny odjazdów, aby tablica odpowiadała temu, co faktycznie robią autobusy. Nic nie kosztuje — tylko sprawia, że zegar mówi prawdę. Domyślnie wyłączone; istniejące rozkłady jazdy pozostają bez zmian, dopóki tego nie włączysz.", ["opt.ProvisionRealFleet.L"]="Dostosuj flotę do rzeczywistego czasu przejazdu (zwiększa liczbę pojazdów)", ["opt.ProvisionRealFleet.D"]="Dobiera również liczbę pojazdów każdej linii do jej RZECZYWISTEJ pętli, a nie do szacunku. To właśnie ta opcja generuje koszty: utrzymanie krótkiego odstępu na linii, której rzeczywista pętla jest ~2x dłuższa od szacunku, wymaga około dwukrotnie więcej pojazdów i dwukrotnie wyższych kosztów utrzymania. Wyłączona (domyślnie) zachowuje liczbę pojazdów opartą na szacunku, więc linia po cichu kursuje z dłuższym faktycznym odstępem niż ustawiony; włączona dostosowuje tabor do rzeczywistej pętli. Tylko zwiększa — nigdy nie schodzi poniżej szacunku — i ma limit, więc błędny pomiar nie zaleje cię autobusami.", ["opt.StopAtEveryStop.L"]="Zatrzymuj na każdym przystanku (nawet pustym)", ["opt.StopAtEveryStop.D"]="Domyślnie Cities: Skylines II pozwala autobusowi POMINĄĆ przystanek, na którym nikt nie czeka i nikt nie chce wysiąść — jedynie zwalnia i przejeżdża, więc taki przystanek nigdy nie jest wstrzymywany do planowego odjazdu i autobus może wyprzedzić swój rozkład jazdy. Przystanek krańcowy jest teraz zawsze zmuszony do zatrzymania, niezależnie od tego ustawienia (jego pominięcie rozstroiłoby cały rozkład). Włącz tę opcję, aby zmusić autobusy do zatrzymania się na KAŻDYM przystanku linii z rozkładem jazdy, tak by każda podana godzina była dotrzymana — kosztem krótkiego postoju na każdym pustym przystanku, przez co linie kursują nieco wolniej. Dotyczy wyłącznie autobusów i innych pojazdów drogowych; pociągi, tramwaje, statki i samoloty i tak zatrzymują się na każdej stacji. Domyślnie wyłączone.", ["opt.RealisticTripsCompat.L"]="Zgodność z Realistic Trips / spowolnionym czasem — włącz, jeśli używasz RT lub Time2Work (ALPHA)", ["opt.RealisticTripsCompat.D"]="Domyślnie wyłączone — zostaw wyłączone, chyba że używasz moda wydłużającego dobę w grze (Time2Work / \"Realistic Trips\" lub podobnego). Włącz z takim modem, a odjazdy, godziny na przystankach i wielkości taboru pozostaną poprawne zamiast kursować przed czasem; mod automatycznie mierzy rzeczywistą długość doby. Bez moda spowalniającego czas to ustawienie nic nie robi, a jeśli mod wykryje taki mod, gdy ta opcja jest wyłączona, odnotuje to w dzienniku. UWAGA: ta ścieżka zgodności jest w wersji ALPHA i NIE została jeszcze przetestowana z Realistic Trips w grze — zgłaszaj wszelkie nieprawidłowości. Pod Realistic Trips twoje linie będą poprawnie używać mniej pojazdów niż wcześniej.", ["opt.MorningPeakStart.L"]="Początek porannego szczytu", ["opt.MorningPeakStart.D"]="Godzina, o której zaczyna się poranny poziom obsługi szczytowej.", ["opt.MorningPeakEnd.L"]="Koniec porannego szczytu", ["opt.MorningPeakEnd.D"]="Godzina, o której kończy się poranny poziom obsługi szczytowej.", ["opt.EveningPeakStart.L"]="Początek wieczornego szczytu", ["opt.EveningPeakStart.D"]="Godzina, o której zaczyna się wieczorny poziom obsługi szczytowej.", ["opt.EveningPeakEnd.L"]="Koniec wieczornego szczytu", ["opt.EveningPeakEnd.D"]="Godzina, o której kończy się wieczorny poziom obsługi szczytowej.", ["opt.NightStart.L"]="Początek nocy", ["opt.NightStart.D"]="Godzina, o której zaczyna się obsługa nocna (może przekraczać północ).", ["opt.NightEnd.L"]="Koniec nocy", ["opt.NightEnd.D"]="Godzina, o której kończy się obsługa nocna.", ["opt.Enabled.L"]="Włącz TransitTimetables", ["opt.Enabled.D"]="Główny przełącznik całego moda. Wyłączony = dokładnie jak w grze podstawowej: każda linia przestaje być zarządzana (wszystkie wstrzymane autobusy są zwalniane, a zastosowana przez mod liczba pojazdów i współczynnik rozgęszczania zostają cofnięte), przy czym twoje rozkłady jazdy poszczególnych linii są zachowane, aby ponowne włączenie je wznowiło. Domyślnie włączony.", ["grp.GroupWindows"]="Okna szczytu", ["grp.GroupRealism"]="Realistyczny czas przejazdu", ["grp.GroupCompat"]="Zgodność", ["grp.GroupStops"]="Przystanki", ["grp.GroupGeneral"]="Ogólne", ["ui.to"]="do", ["ui.timetable"]="ROZKŁAD JAZDY", ["ui.on"]="WŁ.", ["ui.off"]="WYŁ.", ["ui.ttNow"]="teraz co {i} min · {f} pojazdów", ["ui.ttNext"]="następny: {n}", ["ui.firstDeparture"]="Pierwszy odjazd", ["ui.peakInterval"]="Szczyt", ["ui.offPeakInterval"]="Poza szczytem", ["ui.otherHours"]="pozostałe godziny", ["ui.nightInterval"]="Noc", ["ui.customLinePeak"]="Własny szczyt (ta linia)", ["ui.morningPeak"]="Poranny szczyt", ["ui.eveningPeak"]="Wieczorny szczyt", ["ui.customPeakInterval"]="Własny odstęp w szczycie", ["ui.terminusHint"]="Wybierz przystanek, aby zobaczyć jego odjazdy i ustawić go jako przystanek krańcowy tej linii.", ["ui.noLines"]="Żadna linia nie obsługuje tego przystanku.", ["ui.line"]="Linia {n}", ["ui.terminusBadge"]="krańcowy", ["ui.departs"]="odjazd: {d}", ["ui.noDepartures"]="brak zaplanowanych odjazdów", ["ui.notTimetabled"]="brak rozkładu jazdy", ["ui.setTerminusThis"]="Ustaw jako krańcowy", ["ui.setTerminusAll"]="Ustaw jako krańcowy dla wszystkich linii tutaj", ["ui.setTerminusHint"]="Przystanek krańcowy wyznacza rozkład jazdy i wstrzymanie pojazdów; autobusy są tu wycofywane.", ["ui.buttonTooltip"]="Rozkłady jazdy komunikacji", ["ui.panelTitle"]="ODJAZDY", ["ui.panelHint"]="Wybierz przystanek, aby zobaczyć odjazdy wszystkich linii z tego miejsca. Aby edytować rozkład jazdy linii, wybierz linię — jej ustawienia znajdują się w panelu informacyjnym linii.", ["opt.ManageVehicleCount.L"]="Zarządzaj liczbą pojazdów", ["opt.ManageVehicleCount.D"]="Gdy opcja jest włączona (domyślnie), mod ustawia liczbę pojazdów każdej linii z rozkładem jazdy tak, aby utrzymać wybrany odstęp między kursami. Wyłącz ją, aby pozostawić liczbę pojazdów Tobie lub innemu modowi flotowemu (np. All Transit + Truck) – mod nadal wstrzymuje odjazdy na przystanku końcowym, po prostu nie dodaje ani nie zmienia autobusów. Linia z niewystarczającą liczbą pojazdów będzie wtedy kursować z większym odstępem niż ustawiony.", },
                ["pt-BR"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="Tempo de viagem realista (corrige os horários exibidos)", ["opt.RealisticTravelTime.D"]="A própria estimativa do jogo sobre quanto tempo uma linha leva subestima o trajeto real simulado — os ônibus aceleram e freiam em cada parada, algo que a estimativa ignora (medido ao vivo em cerca de 1,7x em linhas com poucas paradas e até ~2,5x nas com muitas paradas). Ative esta opção e o mod mede o trajeto real de cada linha e exibe horários de parada realistas, para que o quadro corresponda ao que os ônibus realmente fazem. Não custa nada — só torna o relógio honesto. Desativado por padrão; as tabelas de horários existentes não mudam até você ativá-lo.", ["opt.ProvisionRealFleet.L"]="Dimensionar a frota pelo tempo de viagem real (aumenta o número de veículos)", ["opt.ProvisionRealFleet.D"]="Também dimensiona a quantidade de veículos de cada linha pelo trajeto REAL em vez da estimativa. Esta é a opção que gasta: manter um intervalo curto em uma linha cujo trajeto real é ~2x a estimativa exige cerca do dobro de veículos, e o dobro de manutenção. Desativado (padrão) mantém a contagem baseada na estimativa, então uma linha roda silenciosamente com um intervalo efetivo maior do que você definiu; ativado dimensiona para o trajeto real. Apenas cresce — nunca reduz uma linha abaixo da estimativa — e é limitado, para que uma leitura ruim não inunde você de ônibus.", ["opt.StopAtEveryStop.L"]="Parar em cada parada (mesmo nas vazias)", ["opt.StopAtEveryStop.D"]="Por padrão, Cities: Skylines II permite que um ônibus PULE uma parada onde ninguém está esperando e ninguém quer descer — ele apenas desacelera e passa, então essa parada nunca é retida até o horário programado de partida e o ônibus pode adiantar-se à sua tabela de horários. O terminal agora é sempre forçado a parar, independentemente desta configuração (pulá-lo desmontaria toda a programação). Ative esta opção para forçar os ônibus a encostar e parar em CADA parada de uma linha com tabela de horários, para que cada horário exibido seja cumprido — ao custo de uma breve espera em cada parada vazia, o que deixa as linhas um pouco mais lentas. Afeta apenas ônibus e outros veículos rodoviários; trens, bondes, navios e aeronaves já param em todas as estações. Desativado por padrão.", ["opt.RealisticTripsCompat.L"]="Compatibilidade com Realistic Trips / tempo lento — ative se você usa RT ou Time2Work (ALFA)", ["opt.RealisticTripsCompat.D"]="Desativado por padrão — deixe desativado a menos que você use um mod que alongue o dia do jogo (Time2Work / \"Realistic Trips\" ou similar). Ative-o com um mod desses e as partidas, horários de parada e tamanhos de frota permanecem corretos em vez de rodar adiantados; o mod mede automaticamente a duração real do dia. Sem um mod de tempo lento esta configuração não faz nada, e se o mod detectar um enquanto isto estiver desativado ele registrará no log. NOTA: este caminho de compatibilidade é ALFA e ainda NÃO foi testado com o Realistic Trips em jogo — por favor, relate qualquer coisa estranha. Sob o Realistic Trips suas linhas usarão corretamente menos veículos do que antes.", ["opt.MorningPeakStart.L"]="Início do pico da manhã", ["opt.MorningPeakStart.D"]="Hora em que começa o nível de serviço do pico da manhã.", ["opt.MorningPeakEnd.L"]="Fim do pico da manhã", ["opt.MorningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da manhã.", ["opt.EveningPeakStart.L"]="Início do pico da noite", ["opt.EveningPeakStart.D"]="Hora em que começa o nível de serviço do pico da noite.", ["opt.EveningPeakEnd.L"]="Fim do pico da noite", ["opt.EveningPeakEnd.D"]="Hora em que termina o nível de serviço do pico da noite.", ["opt.NightStart.L"]="Início da madrugada", ["opt.NightStart.D"]="Hora em que começa o serviço noturno (pode passar da meia-noite).", ["opt.NightEnd.L"]="Fim da madrugada", ["opt.NightEnd.D"]="Hora em que termina o serviço noturno.", ["opt.Enabled.L"]="Ativar TransitTimetables", ["opt.Enabled.D"]="Interruptor mestre de todo o mod. Desativado = jogo original exato: todas as linhas deixam de ser gerenciadas (qualquer ônibus retido é liberado e a contagem de frota e o fator de dispersão aplicados pelo mod são revertidos), enquanto suas tabelas de horários por linha são mantidas para que reativar as retome. Ativado por padrão.", ["grp.GroupWindows"]="Janelas de pico", ["grp.GroupRealism"]="Tempo de viagem realista", ["grp.GroupCompat"]="Compatibilidade", ["grp.GroupStops"]="Paradas", ["grp.GroupGeneral"]="Geral", ["ui.to"]="às", ["ui.timetable"]="TABELA DE HORÁRIOS", ["ui.on"]="LIGADO", ["ui.off"]="DESLIGADO", ["ui.ttNow"]="agora a cada {i} min · {f} veículos", ["ui.ttNext"]="próxima: {n}", ["ui.firstDeparture"]="Primeira partida", ["ui.peakInterval"]="Pico", ["ui.offPeakInterval"]="Fora de pico", ["ui.otherHours"]="outros horários", ["ui.nightInterval"]="Madrugada", ["ui.customLinePeak"]="Pico personalizado (esta linha)", ["ui.morningPeak"]="Pico da manhã", ["ui.eveningPeak"]="Pico da noite", ["ui.customPeakInterval"]="Intervalo de pico personalizado", ["ui.terminusHint"]="Selecione uma parada para ver suas partidas e defini-la como o terminal desta linha.", ["ui.noLines"]="Nenhuma linha atende esta parada.", ["ui.line"]="Linha {n}", ["ui.terminusBadge"]="terminal", ["ui.departs"]="parte: {d}", ["ui.noDepartures"]="nenhuma partida programada", ["ui.notTimetabled"]="sem tabela de horários", ["ui.setTerminusThis"]="Definir como terminal", ["ui.setTerminusAll"]="Definir como terminal para todas as linhas aqui", ["ui.setTerminusHint"]="O terminal ancora a programação e a retenção de veículos; os ônibus se aposentam aqui.", ["ui.buttonTooltip"]="Tabelas de Horários do Transporte", ["ui.panelTitle"]="PARTIDAS", ["ui.panelHint"]="Selecione uma parada para ver as partidas de todas as linhas a partir dela. Para editar a tabela de horários de uma linha, selecione a linha — seus controles estão no painel de informações da linha.", ["opt.ManageVehicleCount.L"]="Gerenciar o número de veículos", ["opt.ManageVehicleCount.D"]="Quando ativado (padrão), o mod ajusta o número de veículos de cada linha com horário para manter o intervalo que você escolher. Desative para deixar o número de veículos por sua conta ou de outro mod de frota (como All Transit + Truck) — o mod continua segurando as partidas no terminal, apenas não adiciona nem altera ônibus. Uma linha com poucos veículos passa então a circular com um intervalo maior do que o definido.", },
                ["ru-RU"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="Реалистичное время в пути (корректировка расписания)", ["opt.RealisticTravelTime.D"]="Собственная оценка игры о продолжительности маршрута занижает реальный, смоделированный круг — автобусы разгоняются и тормозят на каждой остановке, что оценка не учитывает (замерено вживую примерно 1,7x на редких маршрутах и до ~2,5x на маршрутах с частыми остановками). Включите этот параметр, и мод замерит реальный круг каждого маршрута и покажет реалистичное время на остановках, чтобы табло совпадало с тем, что автобусы делают на самом деле. Ничего не стоит — просто делает часы честными. По умолчанию ВЫКЛ; существующие расписания не меняются, пока вы это не включите.", ["opt.ProvisionRealFleet.L"]="Планировать парк по реальному времени в пути (увеличивает число транспортных средств)", ["opt.ProvisionRealFleet.D"]="Также рассчитывать количество транспорта каждого маршрута по РЕАЛЬНОМУ кругу, а не по оценке. Именно этот параметр тратит деньги: удержание плотного интервала на маршруте, чей реальный круг ~2x от оценки, требует примерно вдвое больше транспорта и вдвое больше расходов на содержание. ВЫКЛ (по умолчанию) сохраняет количество по оценке, поэтому маршрут незаметно ходит с более длинным фактическим интервалом, чем вы задали; ВКЛ планирует под реальный круг. Только увеличивает — никогда не урезает маршрут ниже оценки — и ограничено, так что ошибочный замер не завалит вас автобусами.", ["opt.StopAtEveryStop.L"]="Останавливаться на каждой остановке (даже пустой)", ["opt.StopAtEveryStop.D"]="По умолчанию Cities: Skylines II позволяет автобусу ПРОПУСТИТЬ остановку, где никто не ждёт и никто не хочет выйти — он лишь притормаживает и проезжает, поэтому такая остановка никогда не удерживается до запланированного отправления, и автобус может идти с опережением расписания. Конечная станция теперь всегда принудительно требует остановки независимо от этого параметра (её пропуск сорвал бы всё расписание). Включите этот параметр, чтобы автобусы заезжали и останавливались на КАЖДОЙ остановке маршрута с расписанием, чтобы каждое указанное время соблюдалось — ценой короткой стоянки на каждой пустой остановке, из-за чего маршруты идут чуть медленнее. Затрагивает только автобусы и другой дорожный транспорт; поезда, трамваи, суда и самолёты и так останавливаются на каждой станции. По умолчанию ВЫКЛ.", ["opt.RealisticTripsCompat.L"]="Совместимость с Realistic Trips / замедлением времени — включите, если используете RT или Time2Work (АЛЬФА)", ["opt.RealisticTripsCompat.D"]="По умолчанию ВЫКЛ — оставьте выключенным, если только вы не используете мод, удлиняющий игровой день (Time2Work / \\\"Realistic Trips\\\" или подобный). Включите его вместе с таким модом, и отправления, время на остановках и размеры парка останутся корректными вместо опережения; мод автоматически замеряет реальную длину дня. Без мода замедления времени этот параметр ничего не делает, а если мод обнаружит такой при выключенном параметре, он отметит это в журнале. ПРИМЕЧАНИЕ: этот путь совместимости — АЛЬФА и пока НЕ тестировался с Realistic Trips в игре — сообщайте обо всём странном. При Realistic Trips ваши маршруты будут корректно использовать меньше транспорта, чем раньше.", ["opt.MorningPeakStart.L"]="Начало утреннего часа пик", ["opt.MorningPeakStart.D"]="Час, когда начинается уровень обслуживания утреннего часа пик.", ["opt.MorningPeakEnd.L"]="Конец утреннего часа пик", ["opt.MorningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания утреннего часа пик.", ["opt.EveningPeakStart.L"]="Начало вечернего часа пик", ["opt.EveningPeakStart.D"]="Час, когда начинается уровень обслуживания вечернего часа пик.", ["opt.EveningPeakEnd.L"]="Конец вечернего часа пик", ["opt.EveningPeakEnd.D"]="Час, когда заканчивается уровень обслуживания вечернего часа пик.", ["opt.NightStart.L"]="Начало ночи", ["opt.NightStart.D"]="Час, когда начинается ночное обслуживание (может переходить за полночь).", ["opt.NightEnd.L"]="Конец ночи", ["opt.NightEnd.D"]="Час, когда заканчивается ночное обслуживание.", ["opt.Enabled.L"]="Включить TransitTimetables", ["opt.Enabled.D"]="Главный переключатель всего мода. Выкл = точно как в оригинале: все маршруты перестают управляться (любые удержанные автобусы отпускаются, а заданные модом количество транспорта и коэффициент разгруппировки возвращаются к исходным), при этом ваши расписания по маршрутам сохраняются, так что повторное включение их возобновит. По умолчанию ВКЛ.", ["grp.GroupWindows"]="Окна часа пик", ["grp.GroupRealism"]="Реалистичное время в пути", ["grp.GroupCompat"]="Совместимость", ["grp.GroupStops"]="Остановки", ["grp.GroupGeneral"]="Общие", ["ui.to"]="до", ["ui.timetable"]="РАСПИСАНИЕ", ["ui.on"]="ВКЛ", ["ui.off"]="ВЫКЛ", ["ui.ttNow"]="сейчас каждые {i} мин · {f} ед. транспорта", ["ui.ttNext"]="далее: {n}", ["ui.firstDeparture"]="Первое отправление", ["ui.peakInterval"]="Час пик", ["ui.offPeakInterval"]="Вне часа пик", ["ui.otherHours"]="прочие часы", ["ui.nightInterval"]="Ночь", ["ui.customLinePeak"]="Свой час пик (этот маршрут)", ["ui.morningPeak"]="Утренний час пик", ["ui.eveningPeak"]="Вечерний час пик", ["ui.customPeakInterval"]="Свой интервал в час пик", ["ui.terminusHint"]="Выберите остановку, чтобы увидеть её отправления и назначить её конечной станцией этого маршрута.", ["ui.noLines"]="Эту остановку не обслуживают маршруты.", ["ui.line"]="Маршрут {n}", ["ui.terminusBadge"]="конечная", ["ui.departs"]="отправление: {d}", ["ui.noDepartures"]="отправления не запланированы", ["ui.notTimetabled"]="без расписания", ["ui.setTerminusThis"]="Назначить конечной", ["ui.setTerminusAll"]="Назначить конечной для всех маршрутов здесь", ["ui.setTerminusHint"]="Конечная станция закрепляет расписание и удержание транспорта; здесь автобусы выводятся из эксплуатации.", ["ui.buttonTooltip"]="Расписания транспорта", ["ui.panelTitle"]="ОТПРАВЛЕНИЯ", ["ui.panelHint"]="Выберите остановку, чтобы увидеть отправления всех маршрутов от неё. Чтобы изменить расписание маршрута, выберите маршрут — его настройки находятся в информационной панели маршрута.", ["opt.ManageVehicleCount.L"]="Управлять количеством транспорта", ["opt.ManageVehicleCount.D"]="Когда включено (по умолчанию), мод задаёт количество транспорта на каждом маршруте с расписанием, чтобы выдерживать выбранный вами интервал движения. Отключите, чтобы оставить количество транспорта на ваше усмотрение или на управление другого мода для автопарка (например, All Transit + Truck) — мод по-прежнему удерживает отправления на конечной остановке, он просто не добавляет и не меняет автобусы. Маршрут со слишком малым числом транспортных средств тогда будет ходить с интервалом больше заданного.", },
                ["zh-HANS"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="真实旅行时间（修正显示的时刻）", ["opt.RealisticTravelTime.D"]="游戏自身对线路运行时长的估算低于真实模拟的环线用时——公交车在每一站都要加速和刹车，而估算忽略了这一点（实测中，站点稀疏的线路约为 1.7 倍，站点密集的线路可达约 2.5 倍）。开启此项后，模组会测量每条线路的真实环线用时并给出真实的到站时刻，使显示牌与公交车实际运行相符。此项不产生任何花费——它只是让时刻表如实反映现实。默认关闭；在你启用之前，现有时刻表保持不变。", ["opt.ProvisionRealFleet.L"]="根据实际行驶时间配置车队（增加车辆数量）", ["opt.ProvisionRealFleet.D"]="同时按每条线路的真实环线用时（而非估算值）来确定其车辆数量。这一项会产生花费：要在真实环线约为估算值 2 倍的线路上维持紧凑的发车间隔，大约需要两倍的车辆和两倍的维护费。关闭（默认）沿用基于估算的车辆数，导致线路实际运行的发车间隔悄悄比你设定的更长；开启则按真实环线配备车辆。只增不减——绝不会把线路的车辆减到估算值以下——并且有上限，因此一次错误的读数不会让公交车泛滥成灾。", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使无人的站点）", ["opt.StopAtEveryStop.D"]="默认情况下，《都市：天际线 II》允许公交车跳过既无人等候、也无人下车的站点——它只是减速驶过，因此该站点从不会被强制停靠到预定发车时间，公交车便可能提前于时刻表运行。现在无论此设置如何，终点站都始终强制停靠（跳过它会打乱整份时刻表）。开启此项可强制公交车在有时刻表的线路上驶入并停靠每一站，使每个显示的时刻都得到遵守——代价是在每个无人的站点短暂停留，使线路运行略慢一些。仅影响公交车及其他道路车辆；火车、有轨电车、船只和飞机本就在每一站停靠。默认关闭。", ["opt.RealisticTripsCompat.L"]="Realistic Trips / 慢时间兼容——若使用 RT 或 Time2Work 请开启（ALPHA）", ["opt.RealisticTripsCompat.D"]="默认关闭——除非你使用了会延长游戏内一天时长的模组（Time2Work / \"Realistic Trips\" 或类似模组），否则请保持关闭。搭配此类模组时开启，发车时间、到站时刻和车辆数量将保持正确而不会提前运行；模组会自动测量真实的一天时长。若未使用慢时间模组，此设置不起任何作用；若在此项关闭时检测到该类模组，将会在日志中记录提示。注意：此兼容路径为 ALPHA，尚未在游戏内针对 Realistic Trips 测试——如有异常请反馈。在 Realistic Trips 下，你的线路将正确地使用比以往更少的车辆。", ["opt.MorningPeakStart.L"]="早高峰开始", ["opt.MorningPeakStart.D"]="早高峰运营水平开始的时刻。", ["opt.MorningPeakEnd.L"]="早高峰结束", ["opt.MorningPeakEnd.D"]="早高峰运营水平结束的时刻。", ["opt.EveningPeakStart.L"]="晚高峰开始", ["opt.EveningPeakStart.D"]="晚高峰运营水平开始的时刻。", ["opt.EveningPeakEnd.L"]="晚高峰结束", ["opt.EveningPeakEnd.D"]="晚高峰运营水平结束的时刻。", ["opt.NightStart.L"]="夜间开始", ["opt.NightStart.D"]="夜间运营开始的时刻（可能跨过午夜）。", ["opt.NightEnd.L"]="夜间结束", ["opt.NightEnd.D"]="夜间运营结束的时刻。", ["opt.Enabled.L"]="启用 TransitTimetables", ["opt.Enabled.D"]="整个模组的总开关。关闭 = 完全原版：每条线路都不再被管理（任何被暂停的公交车都会放行，模组施加的车辆数和防聚集系数都会还原），同时保留你的各线路时刻表，以便重新启用时恢复。默认开启。", ["grp.GroupWindows"]="高峰时段", ["grp.GroupRealism"]="真实旅行时间", ["grp.GroupCompat"]="兼容性", ["grp.GroupStops"]="站点", ["grp.GroupGeneral"]="常规", ["ui.to"]="至", ["ui.timetable"]="时刻表", ["ui.on"]="开", ["ui.off"]="关", ["ui.ttNow"]="现每 {i} 分钟 · {f} 辆车", ["ui.ttNext"]="下一班：{n}", ["ui.firstDeparture"]="首班发车", ["ui.peakInterval"]="高峰", ["ui.offPeakInterval"]="平峰", ["ui.otherHours"]="其他时段", ["ui.nightInterval"]="夜间", ["ui.customLinePeak"]="自定义高峰（本线路）", ["ui.morningPeak"]="早高峰", ["ui.eveningPeak"]="晚高峰", ["ui.customPeakInterval"]="自定义高峰间隔", ["ui.terminusHint"]="选择一个站点以查看其发车时刻，并将其设为本线路的终点站。", ["ui.noLines"]="没有线路停靠此站点。", ["ui.line"]="线路 {n}", ["ui.terminusBadge"]="终点站", ["ui.departs"]="发车：{d}", ["ui.noDepartures"]="无预定发车", ["ui.notTimetabled"]="无时刻表", ["ui.setTerminusThis"]="设为终点站", ["ui.setTerminusAll"]="设为此处所有线路的终点站", ["ui.setTerminusHint"]="终点站锚定时刻表和车辆暂停；公交车在此退役。", ["ui.buttonTooltip"]="公交时刻表", ["ui.panelTitle"]="发车", ["ui.panelHint"]="选择一个站点以查看每条线路从该站的发车时刻。要编辑某线路的时刻表，请选中该线路——其控件位于该线路的信息面板中。", ["opt.ManageVehicleCount.L"]="管理车辆数量", ["opt.ManageVehicleCount.D"]="开启时（默认），模组会为每条设有时刻表的线路设置车辆数量，以维持你所选的发车间隔。关闭后，车辆数量将交由你自己或其他车队模组（如 All Transit + Truck）来管理——模组仍会在终点站控制发车，只是不再增加或更改公交车。车辆过少的线路此时只会以大于设定值的间隔运行。", },
                ["zh-HANT"] = new Dictionary<string, string> { ["opt.RealisticTravelTime.L"]="真實旅行時間（校正發車時刻表）", ["opt.RealisticTravelTime.D"]="遊戲本身對一條路線所需時間的估算，低估了真實模擬的環線 —— 公車在每一站都要加速與煞車，而估算忽略了這一點（實測站點稀疏的路線約為 1.7 倍，站點密集的路線最高可達約 2.5 倍）。開啟此選項後，模組會實測每條路線的真實環線時間，並張貼真實的靠站時刻，讓時刻表符合公車實際的運行情況。不花任何費用 —— 它只是讓時鐘變得誠實。預設為關閉；在你啟用之前，既有的時刻表維持不變。", ["opt.ProvisionRealFleet.L"]="根據實際行駛時間配置車隊（增加車輛數量）", ["opt.ProvisionRealFleet.D"]="同時依每條路線的「真實」環線時間（而非估算值）來配置車輛數。這是會花錢的選項：要在真實環線約為估算 2 倍的路線上維持緊密班距，需要約兩倍的車輛，也需要兩倍的維護費。關閉（預設）維持以估算為準的車輛數，因此路線實際運行的有效班距會悄悄比你設定的更長；開啟則按真實環線配置。只增不減 —— 絕不會把某條路線的車輛降到估算值以下 —— 並設有上限，因此一次錯誤的讀數不會讓你被公車淹沒。", ["opt.StopAtEveryStop.L"]="每一站都停靠（即使空無一人）", ["opt.StopAtEveryStop.D"]="預設情況下，《Cities: Skylines II》允許公車「跳過」某個既無人等車、也無人下車的站點 —— 它只會減速滑行通過，因此該站不會被保留到其排定的發車時刻，公車便可能領先於時刻表。無論此設定為何，終點站現在一律強制停靠（跳過終點站會使整份時刻表脫節）。開啟此選項可強制公車在有時刻表路線的「每一站」都靠站停車，讓每一個張貼的時刻都被遵守 —— 代價是在每個空站短暫停留，使路線略微變慢。僅影響公車及其他道路車輛；火車、路面電車、船隻與飛機本來就每站皆停。預設為關閉。", ["opt.RealisticTripsCompat.L"]="Realistic Trips／慢速時間相容性 —— 若你使用 RT 或 Time2Work 請開啟（ALPHA）", ["opt.RealisticTripsCompat.D"]="預設為關閉 —— 除非你使用會延長遊戲內一天長度的模組（Time2Work／「Realistic Trips」或類似模組），否則請保持關閉。搭配這類模組時開啟，發車時刻、靠站時刻與車隊規模便會維持正確而不會提早運行；模組會自動實測真實的一天長度。若沒有慢速時間模組，此設定不會有任何作用；而若模組偵測到有這類模組但此設定為關閉，它會在日誌中註記。注意：此相容路徑仍為 ALPHA，尚未在遊戲中對 Realistic Trips 進行測試 —— 若有任何異常請回報。在 Realistic Trips 下，你的路線會正確地使用比以往更少的車輛。", ["opt.MorningPeakStart.L"]="早尖峰開始", ["opt.MorningPeakStart.D"]="早尖峰服務等級開始的時刻。", ["opt.MorningPeakEnd.L"]="早尖峰結束", ["opt.MorningPeakEnd.D"]="早尖峰服務等級結束的時刻。", ["opt.EveningPeakStart.L"]="晚尖峰開始", ["opt.EveningPeakStart.D"]="晚尖峰服務等級開始的時刻。", ["opt.EveningPeakEnd.L"]="晚尖峰結束", ["opt.EveningPeakEnd.D"]="晚尖峰服務等級結束的時刻。", ["opt.NightStart.L"]="夜間開始", ["opt.NightStart.D"]="夜間服務開始的時刻（可能跨越午夜）。", ["opt.NightEnd.L"]="夜間結束", ["opt.NightEnd.D"]="夜間服務結束的時刻。", ["opt.Enabled.L"]="啟用 TransitTimetables", ["opt.Enabled.D"]="整個模組的總開關。關閉＝完全回到原版：每條路線都不再受管理（任何被保留的公車會被釋放，模組套用的車輛數與去群聚係數都會還原），同時保留你的各路線時刻表，以便重新啟用時可繼續使用。預設為開啟。", ["grp.GroupWindows"]="尖峰時段", ["grp.GroupRealism"]="真實旅行時間", ["grp.GroupCompat"]="相容性", ["grp.GroupStops"]="站點", ["grp.GroupGeneral"]="一般", ["ui.to"]="至", ["ui.timetable"]="時刻表", ["ui.on"]="開啟", ["ui.off"]="關閉", ["ui.ttNow"]="目前每 {i} 分鐘 · {f} 輛車", ["ui.ttNext"]="下一班：{n}", ["ui.firstDeparture"]="首班發車", ["ui.peakInterval"]="尖峰", ["ui.offPeakInterval"]="離峰", ["ui.otherHours"]="其他時段", ["ui.nightInterval"]="夜間", ["ui.customLinePeak"]="自訂尖峰（此路線）", ["ui.morningPeak"]="早尖峰", ["ui.eveningPeak"]="晚尖峰", ["ui.customPeakInterval"]="自訂尖峰班距", ["ui.terminusHint"]="選擇一個站點以檢視其發車時刻，並將其設為此路線的終點站。", ["ui.noLines"]="沒有路線行經此站。", ["ui.line"]="路線 {n}", ["ui.terminusBadge"]="終點站", ["ui.departs"]="發車：{d}", ["ui.noDepartures"]="無排定發車", ["ui.notTimetabled"]="無時刻表", ["ui.setTerminusThis"]="設為終點站", ["ui.setTerminusAll"]="設為此處所有路線的終點站", ["ui.setTerminusHint"]="終點站是時刻表與車輛保留的錨點；公車在此退役。", ["ui.buttonTooltip"]="運輸時刻表", ["ui.panelTitle"]="發車時刻", ["ui.panelHint"]="選擇一個站點以檢視每條路線由此站發車的時刻。要編輯某條路線的時刻表，請選取該路線 —— 其控制項位於該路線的資訊面板中。", ["opt.ManageVehicleCount.L"]="管理車輛數量", ["opt.ManageVehicleCount.D"]="開啟時（預設），模組會為每條設有時刻表的路線設定車輛數量，以維持你所選的發車間隔。關閉後，車輛數量將交由你自己或其他車隊模組（如 All Transit + Truck）來管理——模組仍會在終點站控制發車，只是不再增加或變更公車。車輛過少的路線此時只會以大於設定值的間隔運行。", },
        };
